/***********************************************************************************************************************
 * BOARD_INITTEE_BOARD_InitTrustZone function
 **********************************************************************************************************************/
void BOARD_InitTrustZone()
{
    /* SAU configuration */
    
    /* Set SAU Control register: Disable SAU and All Secure */
    SAU->CTRL = 0;
    
    /* Set SAU region number */
    SAU->RNR = 0;
    /* Region base address */
    SAU->RBAR = BOARD_INITTEE_SAU_REGION_0_BASE & SAU_RBAR_BADDR_Msk;
    /* Region end address */
    SAU->RLAR = (BOARD_INITTEE_SAU_REGION_0_END & SAU_RLAR_LADDR_Msk)
        | ((0U << SAU_RLAR_NSC_Pos) & SAU_RLAR_NSC_Msk)
        | ((1U << SAU_RLAR_ENABLE_Pos) & SAU_RLAR_ENABLE_Msk);
    
    /* Set SAU region number */
    SAU->RNR = 1;
    /* Region base address */
    SAU->RBAR = BOARD_INITTEE_SAU_REGION_1_BASE & SAU_RBAR_BADDR_Msk;
    /* Region end address */
    SAU->RLAR = (BOARD_INITTEE_SAU_REGION_1_END & SAU_RLAR_LADDR_Msk)
        | ((0U << SAU_RLAR_NSC_Pos) & SAU_RLAR_NSC_Msk)
        | ((1U << SAU_RLAR_ENABLE_Pos) & SAU_RLAR_ENABLE_Msk);
    
    /* Set SAU region number */
    SAU->RNR = 2;
    /* Region base address */
    SAU->RBAR = BOARD_INITTEE_SAU_REGION_2_BASE & SAU_RBAR_BADDR_Msk;
    /* Region end address */
    SAU->RLAR = (BOARD_INITTEE_SAU_REGION_2_END & SAU_RLAR_LADDR_Msk)
        | ((1U << SAU_RLAR_NSC_Pos) & SAU_RLAR_NSC_Msk)
        | ((1U << SAU_RLAR_ENABLE_Pos) & SAU_RLAR_ENABLE_Msk);
    
    /* Force memory writes before continuing */
    __DSB();
    /* Flush and refill pipeline with updated permissions */
    __ISB();
    
    /* Set SAU Control register: Enable SAU and All Secure (applied only if disabled) */
    SAU->CTRL = ((0U << SAU_CTRL_ALLNS_Pos) & SAU_CTRL_ALLNS_Msk)
        | ((1U << SAU_CTRL_ENABLE_Pos) & SAU_CTRL_ENABLE_Msk);
    
    /* AHB configuration */

    /*--------------------------------------------------------------------
     - AHB Security Level Configurations
     -------------------------------------------------------------------*/
    /* Configuration of AHB Secure Controller
       Possible values for every memory sector or peripheral rule:
        0    Non-secure, User access allowed.
        1    Non-secure, Privileged access allowed.
        2    Secure, User access allowed.
        3    Secure, Privileged access allowed.
    */

    /* Security level configuration of MPC checker */
    AHBSC__AHBSC0->FLASH00_MEM_RULE[0] = 0x33333333U;
    AHBSC__AHBSC0->FLASH00_MEM_RULE[1] = 0;
    AHBSC__AHBSC0->FLASH00_MEM_RULE[2] = 0;
    AHBSC__AHBSC0->FLASH00_MEM_RULE[3] = 0;
    AHBSC__AHBSC0->FLASH01_MEM_RULE[0] = 0;
    AHBSC__AHBSC0->FLASH02_MEM_RULE[0] = 0;
    AHBSC__AHBSC0->ROM_MEM_RULE[0] = 0;
    AHBSC__AHBSC0->ROM_MEM_RULE[1] = 0;
    AHBSC__AHBSC0->ROM_MEM_RULE[2] = 0;
    AHBSC__AHBSC0->ROM_MEM_RULE[3] = 0;
    AHBSC__AHBSC0->RAMX_MEM_RULE[0] = 0;
    AHBSC__AHBSC0->RAMA_MEM_RULE[0] = 0x33333333U;
    AHBSC__AHBSC0->RAMA_MEM_RULE[1] = 0x33333333U;
    AHBSC__AHBSC0->RAMA_MEM_RULE[2] = 0;
    AHBSC__AHBSC0->RAMA_MEM_RULE[3] = 0;
    AHBSC__AHBSC0->RAMB_MEM_RULE[0] = 0;
    AHBSC__AHBSC0->RAMB_MEM_RULE[1] = 0;
    AHBSC__AHBSC0->RAMB_MEM_RULE[2] = 0;
    AHBSC__AHBSC0->RAMB_MEM_RULE[3] = 0;
    AHBSC__AHBSC0->AON_DOMAIN_SRAM_MEM_RULE[0] = 0x33333333U;

    /* Security level configuration of PPC checker */
    AHBSC__AHBSC0->AHB_PERIPHERAL_SLAVE_PORT_P5_SLAVE_RULE0 = 0x00033333U;
    AHBSC__AHBSC0->AHB_PERIPHERAL_SLAVE_PORT_P5_SLAVE_RULE1 = 0x00003000U;
    AHBSC__AHBSC0->APB_PERIPHERAL_GROUP0_MEM_RULE0 = 0x30003303U;
    AHBSC__AHBSC0->APB_PERIPHERAL_GROUP0_MEM_RULE1 = 0x33300303U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP3_MEM_RULE0 = 0x33333333U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP3_MEM_RULE2 = 0x03330000U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP3_MEM_RULE3 = 0x33330000U;
    AHBSC__AHBSC0->AHB_SECURE_CTRL_PERIPHERAL_RULE0 = 0;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP0_MEM_RULE1 = 0x00030003U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP0_MEM_RULE0 = 0x33300000U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP0_MEM_RULE2 = 0x33003033U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP0_MEM_RULE3 = 0x03000033U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP2_MEM_RULE0 = 0x33333330U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP2_MEM_RULE1 = 0x03033333U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP2_MEM_RULE2 = 0x33333303U;
    AHBSC__AHBSC0->AIPS_BRIDGE_GROUP2_MEM_RULE3 = 0x30003333U;
    AHBSC__AHBSC0->AON_DOMAIN_PERIPHERAL_MEM_RULE0 = 0x30003030U;
    AHBSC__AHBSC0->AON_DOMAIN_PERIPHERAL_MEM_RULE1 = 0x00333330U;
    AHBSC__AHBSC0->AON_DOMAIN_PERIPHERAL_MEM_RULE2 = 0x33003003U;
    AHBSC__AHBSC0->AON_DOMAIN_PERIPHERAL_MEM_RULE3 = 0x03330030U;

    /* Security level configuration of MBC checker */
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[0] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[1] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[2] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[3] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[4] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[5] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[6] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM0_BLK_CFG_W[7] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM1_BLK_CFG_W[0] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM1_BLK_CFG_W[1] = 0x88888888U;
    MBC0->MBC_INDEX[0].MBC_DOM0_MEM2_BLK_CFG_W[0] = 0x00008888U;

    /* Security level configuration of masters */
    AHBSC__AHBSC0->MASTER_SEC_LEVEL = 0;
    AHBSC__AHBSC0->MASTER_SEC_ANTI_POL_REG = 0xFFFFFFFFU;

    /*--------------------------------------------------------------------
     - Interrupts: Interrupt security configuration
     -------------------------------------------------------------------*/
    /* Possible values for every interrupt:
     *  0b0    Secure
     *  0b1    Non-secure */
    NVIC->ITNS[0] = 0;
    NVIC->ITNS[1] = 0;
    NVIC->ITNS[2] = 0;
    NVIC->ITNS[3] = 0;
    NVIC->ITNS[4] = 0;
    NVIC->ITNS[5] = 0;

    /* Global Options */
    SCB->AIRCR = (SCB->AIRCR & 0x00009FF7U) | 0x05FA0000U;
    SCB->SCR &= 0xFFFFFFF7U;
    SCB->SHCSR &= 0xFFF7FFFFU;
    SCB->CPACR = 0x00F00000U;
    SCB->NSACR = 0x00000C03U;
    SCnSCB->CPPWR = 0;
    AHBSC__AHBSC0->MISC_CTRL_REG = 0x000086A6U;
    AHBSC__AHBSC0->MISC_CTRL_DP_REG = 0x000086A6U;
}

/***********************************************************************************************************************
 * BOARD_InitBootTEE function
 **********************************************************************************************************************/
void BOARD_InitBootTEE()
{
    BOARD_InitTrustZone();
}
